# pod_leadcond_b_auto.sh : generated by mk_pod_leadcond_b.py l1 1. Runs ON THE POD (nohup). Waits for control q3b-ii, then for a free GPU slot, dry-gates LO_s0 and LCO_s0
# and, only if both pass, starts chain leadcond_b (four fine-tunes of 6,000 steps, card PREREG_V8F_PROOF_ADD35) and the rule-rollout queue LCB behind it.
set -u
W=/workspace/v8proof; Z=$W/runs/leadcond_z; LOG=$Z/lcb_auto.log; cd $W/chain2 || exit 1
ts() { date -u +%Y-%m-%dT%H:%M:%SZ; }
say() { echo "[$(ts)] $*" >> $LOG; }
[ -e $W/chains/leadcond_b ] && { say 'chain leadcond_b exists, nothing done'; exit 0; }
say 'auto start: waits for Q3B_DONE.txt'
k=0; while [ ! -f $Z/Q3B_DONE.txt ]; do [ -f $Z/Q3B_FAIL.txt ] && { say 'Q3B_FAIL.txt present: chain B is NOT started'; echo "q3b failed ($(ts))" > $Z/LCB_NOT_STARTED.txt; exit 1; }; k=$((k+1)); [ $k -gt 600 ] && { say 'no q3b result in 10 h'; echo "no q3b result ($(ts))" > $Z/LCB_NOT_STARTED.txt; exit 1; }; sleep 60; done
say "q3b: $(head -n 1 $Z/Q3B_DONE.txt)"
k=0; while :; do n1=$(nvidia-smi --query-compute-apps=pid --format=csv,noheader 2>/dev/null | grep -c .); sleep 45; n2=$(nvidia-smi --query-compute-apps=pid --format=csv,noheader 2>/dev/null | grep -c .); [ "$n1" -lt 3 ] && [ "$n2" -lt 3 ] && break; k=$((k+1)); [ $k -gt 480 ] && { say 'no free GPU slot in 8 h'; echo "no slot ($(ts))" > $Z/LCB_NOT_STARTED.txt; exit 1; }; sleep 45; done
a=$(grep -E '^anon ' /sys/fs/cgroup/memory.stat | cut -d' ' -f2); m=$(cat /sys/fs/cgroup/memory.max); [ $((m - a)) -gt 20000000000 ] || { say 'less than 20 GB of the memory limit free'; echo "memory ($(ts))" > $Z/LCB_NOT_STARTED.txt; exit 1; }
for arm in LO_s0 LCO_s0; do
  bash dry_gate.sh arms_leadcond_b.txt $arm PREREG_V8F_PROOF_ADD35 > $W/chains/leadcond_dry_$arm.out 2>&1; rc=$?
  say "dry gate $arm rc $rc: $(tail -n 1 $W/chains/leadcond_dry_$arm.out | cut -c1-200)"
  [ $rc = 0 ] && grep -q "ZZ DRY $arm PASS" $W/chains/leadcond_dry_$arm.out || { echo "dry gate $arm did not pass ($(ts))" > $Z/LCB_NOT_STARTED.txt; exit 1; }
done
/workspace/venv/bin/python - >> $LOG 2>&1 <<'PYEOF'
import json
for a in ('LO_s0', 'LCO_s0'):
    s = json.load(open('/workspace/v8proof/runs/motion_dry/%s/out/selfcheck.json' % a)); lv = s.get('levers', {})
    print('SELFCHECK', a, 'dvb', s.get('declared_vs_built'), 'live', (s.get('live') or {}).get('pass'), 'steps_total', s.get('steps_total'), 'lead_cond', lv.get('lead_cond'), 'w_rule_own', lv.get('w_rule_own'), 'form', lv.get('rule_own_form'))
    print('   own probe', json.dumps(s.get('rule_own_probe'))[:600])
    print('   lead_cond probe', json.dumps(s.get('lead_cond_probe'))[:600])
PYEOF
C2_CARD=PREREG_V8F_PROOF_ADD35 C2_WAIT_FOR=$Z/Q3B_DONE.txt C2_IDLE_MIB=30000 nohup setsid bash chain_arms_ft6.sh leadcond_b arms_leadcond_b.txt > $W/chains/leadcond_b_launch.out 2>&1 < /dev/null &
sleep 2; cd $W/distrule || exit 1
nohup setsid bash pod_rtrule_generic.sh LCB leadcond_b LORL_s0:LO_s0 LORL_s1:LO_s1 LCORL_s0:LCO_s0 LCORL_s1:LCO_s1 > $W/distrule/rtrule_LCB_launch.out 2>&1 < /dev/null &
sleep 40; say "chain leadcond_b started: chain processes $(pgrep -f '[c]hain_arms_ft6.sh leadcond_b' | wc -l), queue processes $(pgrep -f '[p]od_rtrule_generic.sh LCB' | wc -l); $(tail -n 1 $W/chains/leadcond_b/chain.log 2>/dev/null | cut -c1-140)"
echo "started $(ts)" > $Z/LCB_STARTED.txt
